answers.body:
The expected OMP gain of parallel work on all a1i[x] which are indeed independent so omp thread safe will be decreased by the cost of increasing a1i[x] vector size dynamically (by calling insert or push_back).
A better solution performance wise would be: vector<vector<int>> a1i = {{},{},{},{},{},{},{}...};

#pragma omp parallel for simd
for(int x = 0;x < a1i.size();x++){
  a1i[x].reserve(x); 
   for(int y = 0; y < x - 1; y++){
      a1i[x].push_back(y);
   }
} or #pragma omp parallel for simd
for(int x = 0;x < a1i.size();x++){
  a1i[x].resize(x); 
   for(int y = 0; y < x - 1; y++){
      a1i[x]= y;
   }
}

