                        static_cast<unsigned char>(retVal / 6),
                        static_cast<unsigned char>(retVal / 5),
                        static_cast<unsigned char>(retVal / 4));

           } 
     } Also time to rule out the really dumb stuff..... Have you included omp.h at least once in your program? Have you enabled omp in the project settings? IIRC, if you haven't done those two things, omp will be disabled under MSVC.

