As mentionned by @Matthieu Brucher , you have an issue with password being shared. Another one is the exit(0); statement. You can only parallelize structured-blocks with a single exit point at the bottom (i.e. more or less a statement block without any exit , return , goto ...). So the exit statement would not be legit. It seems logical: if a thread hits the exit , what are the other ones supposed to do? How do they know that they have to exit too? There are however specific directives to cancel a parallel loop, pretty much what the break; statement would do. The omp cancel directive will signal all threads to break from the parallel loop or parallel region. The omp cancellation point is the point where threads will check if a cancellation has been requested. You'll have to find where the cancellation point should be put: going there too often has a cost in terms of overhead (putting it in the innermost loop may not be efficient), but not often enough means that a thread may keep running for too long before realizing that it should break from its loop (putting it in the outermost loop means that threads will almost never check for cancellation). char password_found[17];
int flag_found=0;
#pragma omp parallel shared(password_found,flag_found)
{
    char password[17] = "################"; //this is a thread private variable

    // These will be done in parallel
    #pragma omp for collapse(3)
    for (int s = 0; s < 6; s++)
    for (int t = 0; t < 6; t++)
    for (int u = 0; u < 6; u++)
    {
        password[0] = alphabet[s];
        password[1] = alphabet[t];
        password[2] = alphabet[u];

        // For every s,t,u, a single thread will loop through these
        for (int v = 0; v < 6; v++)
        for (int w = 0; w < 6; w++)
        for (int x = 0; x < 6; x++) 
        {
            password[3] = alphabet[v];
            password[4] = alphabet[w];
            password[5] = alphabet[x];

            encrypt(plaintext, strlen((char *)plaintext),
                    password, iv, ciphertextnew);

            if (strncmp(ciphertext, ciphertextnew, 16) == 0)
            {
                printf("\n%s", password);
                printf("  Here is the correct key!\n\n");

                flag_found=1;
                strcpy(password_found,password); // Copy thread-private copy to shared variable

                // Now, signal everyone to stop
                #pragma omp cancel parallel
            }

            printf("\n%s is bad", password);

        } // end inner group of loops

        // Threads will check here is they should stop
        #pragma omp cancellation point parallel
    } // end of the outer group of loops
} // end of parallel region

 // Do something now //
if (flag_found){
    printf("\nThe password is %s\n",password_found);
    return 0;
}else{
    printf("Password not found\n");
    return 1;
}

