double sum=0.0;
int i;
for(i=1;i<=N;++i)
    sum += A[i];

return(sum);
}

double fast_sum(double *A, int N){
double sum=0.0;
int i;
#pragma omp parallell for reduction(+:sum) num_threads(NUM_THREADS)
for (i =1; i<=N; ++i)
    sum += A[i];

return(sum);
}  

int main(void)
{
int N = 256;
double sum1, sum2, sum3;
double *A;
int i, h;

A = (double*)malloc(N * sizeof(double));

for( i = 1; i<=N;++i){
    A[i] = i;
}

/* initialization A[N] */

sum1 = serial_sum(A,N);
printf("normal_sum is %f\n", sum1);
sum2 = fast_sum(A,N);
printf("fast_sum is %f\n", sum2);

free(A);
}

