You could reduce the solution values on all threads using the || operator: int sudokuSolution [9][9];

bool solvep(int s[9][9], int row, int col) {    
    bool solution = false;
    #pragma omp parallel for reduction(||:solution)
        for (int val = 1; val < 10; val++) {
            if (isPossible(s,row,col,val)) {
                s[row][col] = val;  
                if (solve(s, row + col / 9, (col + 1) % 9)) {
                    sudokuSolution[row][col] = val;
                    solution = true;
                } else {
                    solution = false;
                } 
            } else {
                 solution = false;
            }
        }
    return solution;
}

