To make sure that a block expression is indeed occupying contiguous memory, use middleCols (or leftCols or rightCols ) instead: #include <Eigen/Core>
template<typename XprType, int BlockRows, int BlockCols, bool InnerPanel>
void inspectBlock(const Eigen::Block<XprType, BlockRows, BlockCols, InnerPanel>& block)
{
    std::cout << __PRETTY_FUNCTION__ << '\n';
}

int main() {
    Eigen::MatrixXi x(8,8);
    inspectBlock(x.block(0, 1, x.rows(), 2));
    inspectBlock(x.middleCols(1, 2));
} Result: void inspectBlock(const Eigen::Block<ArgType, BlockRows, BlockCols, InnerPanel>&) [with XprType = Eigen::Matrix<int, -1, -1>; int BlockRows = -1; int BlockCols = -1; bool InnerPanel = false]
void inspectBlock(const Eigen::Block<ArgType, BlockRows, BlockCols, InnerPanel>&) [with XprType = Eigen::Matrix<int, -1, -1>; int BlockRows = -1; int BlockCols = -1; bool InnerPanel = true] Note: -1 is the value of Eigen::Dynamic , i.e., not fixed at compile time. And of course, if your matrix was row major, you could split int topRows , middleRows or bottomRows , instead.

