First, like hinted in the comment, use omp_get_wtime() instead of clock() (it will give you the number of clock ticks accumulated across all threads) measure the time. Second, If I recall correctly, this algorithm have load balancing problems, so try to use a dynamic scheduling: //timer start
double begin = omp_get_wtime();

#pragma omg parallel for private(j,x,y, esc_time) schedule(dynamic, 1)
for(i = 0; i < w; ++i) {
    x = x0 + i * dx;
    for(j = 0; j < h; ++j) {
        y = y1 - j * dy;
        esc_time = escape_time(x, y, max_iter);

        canvas[ GET_R(i, j, w) ] = color_buffer[esc_time * 3];
        canvas[ GET_G(i, j, w) ] = color_buffer[esc_time * 3 + 1];
        canvas[ GET_B(i, j, w) ] = color_buffer[esc_time * 3 + 2];

      }
}

//time calculation
double end = omp_get_wtime();
double time_spent = (double)(end - begin) / CLOCKS_PER_SEC;
