You almost got it right, but Vaes_cipher_top* top; should be moved before the if statement, e.g. immediately after the opening brace of the while loop. Also in this case top would not be visible outside the parallel region. I would suggest that you restructure the code as follows: int main(int argc, char **argv, char **env)
{
   Verilated::commandArgs(argc, argv);

   #pragma omp parallel num_threads(2)
   {
      unsigned int i = 0;
      unsigned int set_done;
      unsigned int ld_set = 0;
      //top->rst = 1;           // assert reset
      unsigned int iter_count = 1;
      Vaes_cipher_top* top = new Vaes_cipher_top;  // this is the aes object that will do the enc

      while (i < 2)
      {
         if (iter_count)
         {
            top = new Vaes_cipher_top;
            iter_count = 0; 
         }
         if (main_time == 0)
            top-> rst = 1;  //assert reset
         if (main_time > 10)
         {
            top->rst = 0;   // Deassert reset
         }
         if ((main_time % 10) == 1)
         {
            top->clk = 1;       // Toggle clock (posedge)
         }
         if ((main_time % 10) == 6)
         {
            top->clk = 0;
            //setting DUT values

            if (ld_set!=1 && main_time > 10)
            {
               top->ld = 1;
               top->key     = {0x00000000,0x00000000,0x00000000,0x00000000};
               top->text_in = {0x00000000,0x00000000,0x00000000,0x00000000};
               ld_set++;
            }
            else if (ld_set == 1 && main_time > 10)
            {
               top->ld = 0;
               set_done = 0;
            }
         } //(main_time % 10) == 6)

         top->eval();            // Evaluate model

         if (top->done && !set_done)
         {
            print(top->key);
            print(top->text_in);
            print(top->text_out);
            ld_set = 0; //reset  
            i++;
            set_done  = 1;
            iter_count = 1; 
         } //if(top->done)

         main_time++;            // Time passes...
      } //end of while 

      top->final();               // Done simulating

      delete top;
   }

   printf("\nTest Done\n");

   return 0;
} //end of main Though this has nothing to do with OpenMP, the above code leaks memory. top is being allocated anew each time when iter_count is non-zero, which happens when the if (top->done && !set_done) conditional is true and i is still equal to 0 . Probably you should think about how to remedy that problem.

