The number variable is incremented globally and hence creates a barrier; no computation can be done in parallel, each thread must wait for the previous one to end so that the number+=2 part is consistent. You can circumvent this by creating another, thread-specific variable (here n ) whose value is based on the loop index ( i ) One pragma omp parallel for is sufficient: #include <stdio.h>
#include <time.h>
#include <omp.h>
#define CHUNKSIZE 750000
//#define CHUNKSIZE2 2500

// Program computes the total number of primes larger than 100000001 and smaller than 16000001.
int main() {

int number = 100000001;
int n;
int primes[20];
int i, j, is_prime, index = 0, nprimes = 0;
time_t start_time, end_time;

start_time = time(NULL);
int chunk = CHUNKSIZE;
//int chunk2 = CHUNKSIZE2;

#pragma omp parallel for private(n, is_prime, j)
for (i = 0; i < 300000; i++) {
    // get the next number to check if it is a prime
    //number += 2;
    n = number + i*2;
    is_prime = 1;
    //#pragma omp parallel for schedule (dynamic, chunk2)
    for (j = 2; j < 10001; j++) {
        if ((n % j) == 0) {
            is_prime = 0;
            break;
        }
    }
    // f0und a prime number. Count it and save the first 20 primes
    if (is_prime) nprimes++;
    if (is_prime && (index < 20)) {
        primes[index] = n;
        index++;
    }
}

 for (i = 0; i < 20; i++)
    printf("%d is prime\n", primes[i]);
    end_time = time(NULL);
    printf("number of primes = %d, elapsed time is %d seconds\n", nprimes, end_time - start_time);
 //return 0;

