struct Ran
{
  Ullong u, v, w;
  Ran(Ullong j) : v(4101842887655102017LL), w(1)
  {
    u = j ^ v; int64();
    v = u; int64();
    w = v; int64();
  }
  inline Ullong int64()
  {
    u = u * 2862933555777941757LL + 7046029254386353087LL;
    v ^= v >> 17; v ^= v << 31; v ^= v >> 8;
