template <typename T>
void ca_epi_data(Rcpp::XPtr<BigMatrix> epi_data,
                                  const Rcpp::XPtr<BigMatrix> combos,
                                  const arma::mat& epi1,
                                  const arma::mat& epi2,
                                  const arma::mat& TRAN,
                                  const NumericMatrix& Y,
                                  const NumericMatrix& trdata1,
                                  const NumericMatrix& trdata2,
                                  int threads=0) {
