answers.body:
Finally, I ended up by a semi-elegant way: I put the code to call in parallel and serial to an extra file and use some pre-processor defines to handle the omp statements. This omits code duplication and keeps the code half-way readable: //------------------------
//FILE callMethod.hpp:

local_pragma_omp_for()
  for (int i=0; i<100; ++i)
  {
    std::cout<<"Hello from thread " << omp_get_thread_num() <<" and iter "<<k<<std::endl;
  }
//FILE callMethod.hpp:
//------------------------

int main(int argc, char *argv[])
{
  int a = 1000;
  if (argc > 2)
    a= (int)argv[1];

  #define DO_PRAGMA(x) _Pragma(#x)

  #pragma omp parallel
  {
    if (a < 4)
    {
        #define local_pragma_omp_for() DO_PRAGMA(omp for)
        #include "callMethod.hpp"
        #undef local_pragma_omp_for
    }
    else
    {
      #pragma omp single
      {
        #define local_pragma_omp_for()  // empty, to no write the statement
        #include "callMethod.hpp"
        #undef local_pragma_omp_for
      }
    }
  }
}

