long double trapezoidal_method(long double local_a, long double local_b, int num_intervals, int num_threads) {

    omp_set_num_threads(num_threads);

    long double h = (local_b - local_a) / (double)num_intervals;
    long double total_sum = 0;

    long double global_b = local_b;

    #pragma omp parallel shared(total_sum)
    {
        #pragma omp for reduction(+:total_sum)

        for (int i = 1; i < num_intervals; i++) {
            long double a = local_a + (i - 1) * h;
            long double b = local_a + i * h;

            total_sum +=  0.5 * (function(a) + function(b)) * h;
        }

    }
    //printf("%Lf \n",total_sum);
    return total_sum;
}

int main(int argc, char *argv[]) {
    int rank, size;
    MPI_Status status;

    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    long double partial_sum, global_sum;

    long double parameters[3];

    double start_time, end_time;

    long double interval_start = -1;
    long double interval_end = 1;
    int num_intervals = 100000000;

    int num_threads = atoi(argv[1]);

    int intervals_per_process = (int) floor(num_intervals / size);

    long double step_per_process = (interval_end - interval_start) / size;

    start_time = omp_get_wtime();

    if (rank == 0) {
        partial_sum = 0;

        long double a = interval_start;
        long double b = interval_start + step_per_process;

        int intervals_left = num_intervals;

        for (int i = 1; i < size; i++) {
            long double parameters[3] = {a, b, intervals_per_process};

            MPI_Send(parameters, 3, MPI_LONG_DOUBLE , i, 0, MPI_COMM_WORLD);

            a = b;
            b += step_per_process;
            intervals_left -= intervals_per_process;
        }

        partial_sum = trapezoidal_method(a, interval_end, intervals_left, num_threads);
    } else {
        MPI_Recv(&parameters, 3, MPI_LONG_DOUBLE, 0, 0, MPI_COMM_WORLD, &status);
        partial_sum = trapezoidal_method(parameters[0], parameters[1], parameters[2], num_threads);
    }

    MPI_Reduce(&partial_sum, &global_sum, 1, MPI_LONG_DOUBLE, MPI_SUM, 0, MPI_COMM_WORLD);

    end_time = omp_get_wtime();

    if (rank == 0) {   
        printf("Processes: %d | Threads: %d | Intervals per process: %d | Sum: %Lf | Execution time: %f s. \n", size, num_threads, intervals_per_process, global_sum, end_time - start_time);
    }

    MPI_Finalize();
    return 0;
}

